function loader(candidate=false){const cache=new Map(),loads=[];function read(relative){const contract=!candidate&&packet.contracts.find(c=>relative===dir+c.file);return fs.readFileSync(S+'/'+(contract?dir+contract.impl+'.ts':relative),'utf8');}function load(relative){relative=path.normalize(relative);if(cache.has(relative))return cache.get(relative);loads.push(relative);const exports={};cache.set(relative,exports);const output=ts.transpileModule(read(relative),{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.CommonJS}}).outputText;new Function('require','exports',output)(spec=>load(path.resolve('/',path.dirname(relative),spec+'.ts').slice(1)),exports);return exports;}return{load,loads,read};}
function sourceComponents(v,out=[]){if(Array.isArray(v)){for(const x of v)sourceComponents(x,out);}else if(v&&typeof v==='object'){if(v.city&&v.objectId&&v.partId&&v.batches){out.push(v);return out;}for(const x of Object.values(v))sourceComponents(x,out);}return out;}
function digest(module,c,rows,x){const count=rows.reduce((n,r)=>n+r.batches.reduce((m,b)=>m+b.positions.length/3,0),0),color=new Float32Array(count*4).fill(.125),frames=new Float32Array(count*5).fill(-.25),input=hash(rows),stats=module[c.apply](rows,color,frames,x);assert.equal(hash(rows),input,'source geometry/material input stays unchanged');return{stats,colorSHA256:hash(Buffer.from(color.buffer)),frameSHA256:hash(Buffer.from(frames.buffer)),bindings:rows.map(r=>module[c.binding](r)),inputSHA256:input};}
const dummy=city=>({city,objectId:'osm/way/1',partId:'unrelated',origin:[0,0],componentGeometry:{type:'Polygon',coordinates:[]},sourceFeature:{properties:{}},batches:[{positions:[0,0,0],normals:[0,1,0],indices:[0],color:[0,0,0]}]});
const context=(city,f)=>({city,indexSHA:f.indexSHA,sourcePBF:f.sourcePBF,boundarySHA:f.boundarySHA,sourceSnapshot:f.sourceSnapshot,pathsReady:{color:true,shadow:true,pick:true},signal:new AbortController().signal,leafSHA:c=>c.proof?.sourceSHA256,materialReady:()=>true});
test('44 exact fixture contracts: original functions and full/partial/invalid/material hashes agree',async()=>{
 const original=loader(),candidate=loader(true),registry=candidate.load(dir+'inline-city-materials.ts'),proof=[];
 // Berlin and unrelated same-city bindings preserve no-match contracts without parsing any selected fixture.
 await registry.prepareInlineCityMaterials('berlin',new AbortController().signal);for(const c of packet.contracts){const before=candidate.load(dir+c.file),base=original.load(dir+c.file);for(const city of ['berlin',c.city]){const rows=[dummy(city)],x=context(c.city,{});assert.deepEqual(digest(before,c,rows,x),digest(base,c,rows,x));}assert.equal(before[c.binding]({...c.ids[0],city:'berlin'}),false);assert.throws(()=>before[c.binding](c.ids[0]),/not prepared/);}
 assert(!candidate.loads.some(p=>/-fixture\.ts$/.test(p)),'cold facades do not load fixture data');
 let waits=0;for(const city of ['munich','dresden'])await registry.prepareInlineCityMaterials(city,new AbortController().signal,p=>{waits++;return p;});assert.equal(waits,46);
 for(const c of packet.contracts){const base=original.load(dir+c.file),next=candidate.load(dir+c.file),fixtures=c.fixtures.map(f=>original.load(dir+f.slice(2)+'.ts')),primary=Object.values(fixtures[0])[0],all=fixtures.flatMap(f=>sourceComponents(f)),rows=[...new Map(all.filter(r=>base[c.binding](r)).map(r=>[r.city+'|'+r.objectId+'|'+r.partId,r])).values()],x=context(c.city,primary);assert(rows.length>0,c.file+' genuine carriers');
  const cases={full:rows,partial:rows.slice(0,1),invalid:rows.map((r,i)=>i?r:{...r,origin:[r.origin[0]+.01,r.origin[1]]}),other:[dummy('berlin')]},outputs={};
  for(const [label,input]of Object.entries(cases)){const a=digest(base,c,input,x),b=digest(next,c,input,x);assert.deepEqual(b,a,c.file+' '+label);outputs[label]=a;}
  assert(outputs.full.stats.painted>0,c.file+' original positive paint');const aborted=context(c.city,primary);aborted.signal=AbortSignal.abort();assert.deepEqual(digest(next,c,rows,aborted),digest(base,c,rows,aborted));assert.deepEqual(digest(next,c,rows,{...x,indexSHA:'invalid'}),digest(base,c,rows,{...x,indexSHA:'invalid'}));
  const impl=candidate.read(dir+c.impl+'.ts'),source=original.read(dir+c.file);assert.equal(hash(impl),c.implementationSHA256,'original implementation retained');proof.push({file:c.file,originalSHA256:hash(source),implementationSHA256:hash(impl),outputs});
 }
 assert.equal(candidate.loads.filter(f=>/-implementation\.ts$/.test(f)).length,46);assert.equal(proof.length,46);
});
test('prepare cancellation, simultaneous observers, rejected session and retry keep finite readiness',async()=>{
 const {createLazyCityMaterial}=loader(true).load(dir+'lazy-city-material.ts');let release,imports=0;const value={ok:true},route=createLazyCityMaterial('test',()=>{imports++;return new Promise(r=>release=r);}),a=new AbortController(),b=new AbortController();const first=route.prepare(a.signal).catch(e=>e.name),second=route.prepare(b.signal);await Promise.resolve();a.abort();assert.equal(await first,'AbortError');assert.equal(route.value(),undefined);assert.throws(()=>route.required(),/not prepared/);release(value);await second;assert.equal(route.value(),value);assert.equal(imports,1);
 let later;const pending=createLazyCityMaterial('pending',()=>new Promise(r=>later=r));await assert.rejects(pending.prepare(new AbortController().signal,()=>Promise.reject(Error('session rejected'))),/session rejected/);assert.equal(pending.value(),undefined);const next=pending.prepare(new AbortController().signal);await Promise.resolve();later(value);await next;assert.equal(pending.required(),value);
 let attempts=0;const failed=createLazyCityMaterial('retry',async()=>{if(++attempts===1)throw Error('import failure');return value;});await assert.rejects(failed.prepare(new AbortController().signal),/import failure/);await failed.prepare(new AbortController().signal);assert.equal(attempts,2);assert.equal(failed.required(),value);
 const pre=AbortSignal.abort();await assert.rejects(route.prepare(pre),{name:'AbortError'});
});
