 const compiled=ts.transpileModule(tsbody+'\nreturn shard;', {compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.None}}).outputText,shard=new Function(...Object.keys(scope),compiled)(...Object.values(scope)),abort=new AbortController(),pending=shard({tile_key:'a',sha256:'sha',path:'/x'},abort.signal);await new Promise(r=>setImmediate(r));assert.deepEqual(calls,['c358','inline','wait']);assert.equal(remembered,0);abort.abort();await assert.rejects(pending,{name:'AbortError'});assert.equal(remembered,0);
 calls.length=0;const passed=shard({tile_key:'b',sha256:'sha',path:'/x'},new AbortController().signal);await new Promise(r=>setImmediate(r));release();await passed;assert.deepEqual(calls,['c358','inline','wait','verify']);assert.equal(remembered,1);
